mod solution;

fn main() {
    let cases = [
    (r#"insert5 insert2 insert8 insert1 delete2 inorder"#, r#"1,5,8"#),
    (r#"insert4 insert2 delete4 inorder"#, r#"2"#),
    (r#"
insert4 insert2 delete4 inorder
"#, r#"2"#),
    (r#"  
insert5 insert2 insert8 insert1 delete2 inorder
  "#, r#"1,5,8"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS treap");
}
